-- Venue Live Guest "Birthday Taman Peri". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara tamanperi), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'tamanperi', 'Birthday Taman Peri (taman ajaib)', 'tamanperi', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 129, 'center 38%',
  $t${"name":"Taman Peri","orn":"blossom","ui":{"ivory":"#FBF5FF","white":"#FFFFFF","soft":"#F1E3FA","soft2":"#D9B8EE","accent":"#A55CC8","deep":"#5E2F80","ink":"#46235F","mute":"#8D6BA6","line":"#E8D3F3","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FEFAFF","ink":"#46235F","accent":"#A55CC8","gold":"#E8B04A","leaf":"#F1E3FA","hbg":"rgba(251,245,255,.94)","hline":"#D9B8EE","motif":"blossom"},"hud":{"bg":"rgba(94,47,128,.86)","acc":"#FFD36E","on":"#46235F"},"scr":{"wine":"#5E2F80","veil":"251,245,255"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'tamanperi');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/tamanperi/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/tamanperi/balloons.webp","w":1.3,"x":3.3,"z":-18,"mirror":true},"stall_snacks":{"url":"/assets/live-decor/tamanperi/stall_snacks.webp","w":2.0},"stall_candy":{"url":"/assets/live-decor/tamanperi/stall_candy.webp","w":1.4},"stall_drinks":{"url":"/assets/live-decor/tamanperi/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/tamanperi/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/tamanperi/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/tamanperi/arch.webp"},"fountain":{"url":"/assets/live-decor/tamanperi/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/tamanperi/sign.webp","w":1.5},"easel":{"url":"/assets/live-decor/tamanperi/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/tamanperi/table.webp"},"banner":{"url":"/assets/live-decor/tamanperi/banner.webp","w":1.8},"gifts":{"url":"/assets/live-decor/tamanperi/gifts.webp","w":1.8},"lamp":{"url":"/assets/live-decor/tamanperi/lamp.webp","w":1.3,"x":3.3,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/tamanperi/rope.webp","w":1.3,"x":3.3,"z":-6,"mirror":true},"planter":{"url":"/assets/live-decor/tamanperi/planter.webp","w":1.3,"x":3.3,"z":0,"mirror":true},"bush":{"url":"/assets/live-decor/tamanperi/bush.webp","w":1.3,"x":3.3,"z":6,"mirror":true},"av_host":{"url":"/assets/live-decor/tamanperi/av_host.webp","name":"Arka Pangeran Peri"},"av_l1":{"url":"/assets/live-decor/tamanperi/av_l1.webp","name":"Kak Topi Lentera"},"av_l2":{"url":"/assets/live-decor/tamanperi/av_l2.webp","name":"Kak Jubah Daun"},"av_l3":{"url":"/assets/live-decor/tamanperi/av_l3.webp","name":"Kak Penjelajah"},"av_p1":{"url":"/assets/live-decor/tamanperi/av_p1.webp","name":"Kak Gaun Kelopak"},"av_p2":{"url":"/assets/live-decor/tamanperi/av_p2.webp","name":"Kak Hijab Lilac"},"av_p3":{"url":"/assets/live-decor/tamanperi/av_p3.webp","name":"Kak Hijab Tongkat"}}$d$::jsonb, background_url = '/assets/live-decor/tamanperi/painting.webp', active = true, updated_at = now() where key = 'tamanperi';
